void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 position = (fragCoord / iResolution.xy) * 2.0 - 1.0;
    position.x += iTime * 0.2;

    // Procedural color yippee
    vec3 color = pow(
        sin(position.x * 5.0 + vec3(0.0, 1.0, 2.0) * 3.1415 * 2.0 / 3.0) * 0.5 + 0.5,
        vec3(2.0)
    ) * (exp(abs(position.y) * 4.0) - 1.0);

    // Exposure and white point control (adjustable parameters)
    float exposure = 1.0;     // Can be adjusted for brightness control
    float whitePoint = 1.0;   // White reference (1.0 = neutral)

    // Lower half
    if (position.y < 0.0) {
        color = tonemap(color, exposure, whitePoint);
    } else {
        color = Srgb3(color);
    }

    fragColor = vec4(color, 1.0);
}

#define F1 float
#define F3 vec3

// sRGB <-> Linear conversion functions
F1 Linear1(F1 c) { return (c <= 0.04045) ? c / 12.92 : pow((c + 0.055) / 1.055, 2.4); }
F3 Linear3(F3 c) { return F3(Linear1(c.r), Linear1(c.g), Linear1(c.b)); }
F1 Srgb1(F1 c) { return (c < 0.0031308) ? c * 12.92 : 1.055 * pow(c, 0.41666) - 0.055; }
F3 Srgb3(F3 c) { return F3(Srgb1(c.r), Srgb1(c.g), Srgb1(c.b)); }

// Convert linear RGB to OKLab (perceptual space)
vec3 rgb_to_oklab(vec3 c) {
    float l = 0.4121656120 * c.r + 0.5362752080 * c.g + 0.0514575653 * c.b;
    float m = 0.2118591070 * c.r + 0.6807189584 * c.g + 0.1074065790 * c.b;
    float s = 0.0883097947 * c.r + 0.2818474174 * c.g + 0.6302613616 * c.b;

    float l_ = pow(l, 1.0/3.0);
    float m_ = pow(m, 1.0/3.0);
    float s_ = pow(s, 1.0/3.0);

    return vec3(
         0.2104542553 * l_ + 0.7936177850 * m_ - 0.0040720468 * s_,
         1.9779984951 * l_ - 2.4285922050 * m_ + 0.4505937099 * s_,
         0.0259040371 * l_ + 0.7827717662 * m_ - 0.8086757660 * s_
    );
}

// Convert OKLab back to linear RGB
vec3 oklab_to_rgb(vec3 c) {
    float l_ = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
    float m_ = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
    float s_ = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;

    float l = l_ * l_ * l_;
    float m = m_ * m_ * m_;
    float s = s_ * s_ * s_;

    return vec3(
         4.0767245293 * l - 3.3072168827 * m + 0.2307590544 * s,
        -1.2681437731 * l + 2.6093323231 * m - 0.3411344290 * s,
        -0.0041119885 * l - 0.7034763098 * m + 1.7068625689 * s
    );
}

vec3 tonemap(vec3 linearRGB, float exposure, float whitePoint) {
    linearRGB *= exposure;
    vec3 okl = rgb_to_oklab(linearRGB);
    float L = okl.x;
    const float a = 1.8, b = -0.02;
    const float c = 1.75, d = 0.62, e = 0.15;
    okl.x = (L * (a * L + b)) / (L * (c * L + d) + e);

    // Apply white point control
    okl.x = clamp(okl.x / whitePoint, 0.0, 1.0);

    // --- Adaptive Chroma Compression ---
    float chroma = length(okl.yz);
    if (chroma > 0.0) {
        float limit = 1.2;
        float compressed = chroma / (1.0 + pow(chroma, limit));
        okl.yz *= compressed / chroma;
    }

    // Return RGB
    vec3 rgb = oklab_to_rgb(okl);
    rgb = max(rgb, vec3(0.0));

    // --- ACES Output Transform ---
    rgb = rgb / (rgb + vec3(1.0));

    // Final sRGB encoding
    return Srgb3(rgb);
}
